#!/bin/sh
# Regenerates the stub headers/sources of the private frameworks of the desktop from docs/desktop/frameworks/*.objc.txt (see sdk/build-frameworks.sh): every framework in that folder.
cd "$(dirname "$0")/.." || exit 1
mkdir -p sdk/include/wsbsd/standins; rm -f sdk/include/wsbsd/standins/*.txt
ALL="$(ls docs/desktop/frameworks | sed 's/\.objc\.txt$//' | tr '\n' ' ')"
for n in $ALL; do
	mkdir -p sdk/include/$n sdk/src/$n; python3 tools/impl_skips.py sdk/src/$n/*_impl.m > /tmp/$n.skips 2>/dev/null; touch /tmp/$n.skips
	set -- $(python3 tools/framework_deps.py $n $ALL); IMPS="$1"; KNOWN="$2"
	python3 tools/gen_objc_stubs.py docs/desktop/frameworks/$n.objc.txt $n sdk/include/$n --skip /tmp/$n.skips --standins sdk/include/wsbsd/standins --imports "AppKit/AppKit.h,QuartzCore/QuartzCore.h,wsbsd/FrameworkStandIns.h${IMPS:+,$IMPS}" ${KNOWN:+--known-from $KNOWN} > /dev/null 2>&1 && mv sdk/include/$n/${n}_Generated.m sdk/src/$n/ || echo "generation failed: $n"
done
echo "$ALL" > sdk/frameworks.list
(echo "/* the superclasses of the stub frameworks that are not part of this stack (generated by tools/regen_frameworks.sh) */"; echo "#import <Foundation/Foundation.h>"; cat sdk/include/wsbsd/standins/*.txt | sort -u | grep -v "^$" | while read c; do echo "@interface $c : NSObject @end"; done) > sdk/include/wsbsd/FrameworkStandIns.h
